CREATE OR REPLACE FUNCTION calculate_fei(
    engagement_rate NUMERIC,
    social_interaction_score NUMERIC,
    active_days_per_week INTEGER,
    average_sessions_per_day INTEGER
) RETURNS NUMERIC AS $$
BEGIN
    RETURN (
        engagement_rate * 0.3 +
        social_interaction_score * 0.2 +
        active_days_per_week * 0.25 +
        average_sessions_per_day * 0.25
    );
END;
$$ LANGUAGE plpgsql;

